function dec4(str){const pts=[];let i=0,la=0,lo=0;while(i<str.length){for(const which of [0,1]){let b,sh=0,res=0;do{b=str.charCodeAt(i++)-63;res|=(b&0x1f)<<sh;sh+=5}while(b>=0x20);const d=(res&1)?~(res>>1):(res>>1);if(which===0)la+=d;else lo+=d}pts.push([la/1e4,lo/1e4])}return pts}
